// WLED-Docs' published reference animations and palette stops from this checkout.
// https://kno.wled.ge/features/effects/; see reference-previews.json for provenance.
const references=parent.canvasReferencePreviews;
effects.splice(0,effects.length,...references.effects.map(effect=>({...effect,swatch:'#000000'})));
palettes.splice(0,palettes.length,...references.palettes.map(palette=>palette.name));
const motionPreference=matchMedia('(prefers-reduced-motion:reduce)');
let randomSeed=5727;
const randomReferenceColors=Array.from({length:4},()=>Array.from({length:3},()=>{randomSeed^=randomSeed<<13;randomSeed^=randomSeed>>>17;randomSeed^=randomSeed<<5;return randomSeed>>>24;}));

// Dynamic palettes resolve the same c1/c2/c3 placeholders as WLED's web UI.
function paletteStops(name=state.palette) {
	const definition=references.palettes.find(palette=>palette.name===name)||references.palettes[4];
	const colors=[state.color,state.secondaryColor||'#000000',state.tertiaryColor||'#000000'];
	const defaultId=effects.find(effect=>effect.name===state.effect)?.defaultPalette||6;
	const data=definition.stops||references.palettes[defaultId].stops;
	const stops=data.map((entry,index)=>{
		if(Array.isArray(entry))return [entry[0],entry.slice(1)];
		if(entry==='r')return [Math.round(index/data.length*255),randomReferenceColors[index%4]];
		const hex=colors[Number(entry[1])-1];
		return [Math.round(index/data.length*255),hex.match(/[\da-f]{2}/gi).map(channel=>parseInt(channel,16))];
	});
	if(stops.length===1)stops.push([255,stops[0][1]]);
	return stops;
}

// Match genPalPrevCss in wled00/data/index.js without invented pastel colors.
function paletteGradient(name) {
	return 'linear-gradient(to right,'+paletteStops(name).map(([position,rgb])=>'rgb('+rgb.join(',')+') '+Math.round(position/255*100)+'%').join(',')+')';
}

// Solid uses the selected primary color; recorded effects keep their reference colors.
function effectThumbnail(name,animate=false) {
	const reference=references.effects.find(effect=>effect.name===name)||references.effects[0];
	if(reference.id===0)return `<span class="effect-thumb reference-effect" data-reference-id="0" title="Solid · primary color" style="background:${state.color}"></span>`;
	const moving=animate&&!motionPreference.matches;
	return `<span class="effect-thumb reference-effect" data-reference-id="${reference.id}" title="${reference.name} · WLED reference colors"><img alt="" src="${moving?reference.animation:reference.still}" data-animated="${reference.animation}" data-still="${reference.still}" data-preview-selected="${animate}" style="object-fit:${reference.width>reference.height?'fill':'contain'}"></span>`;
}

// Normalize saved settings from the earlier sample catalogs before rendering.
function normalizeReferenceState() {
	if(!effects.some(effect=>effect.name===state.effect))state.effect=state.effect==='Noise'?'Fill Noise':state.effect==='Ocean'?'Palette':'Blends';
	if(!palettes.includes(state.palette))state.palette=state.palette==='Ice'?'Icefire':'Color Gradient';
}
const renderBeforeReferences=render;
render=function(){normalizeReferenceState();renderBeforeReferences();};

// Replace the existing selector and picker thumbnails after every redraw.
function decorateReferences() {
	const effectSelector=document.getElementById('effect-selector');
	effectSelector.querySelector('.effect-thumb').outerHTML=effectThumbnail(state.effect,true);
	effectSelector.querySelector('strong').textContent=state.effect;
	const paletteSelector=document.getElementById('palette-selector');
	paletteSelector.querySelector('.effect-thumb').outerHTML=`<span class="effect-thumb reference-palette" data-palette-id="${references.palettes.find(palette=>palette.name===state.palette).id}" style="background:${paletteGradient(state.palette)}"></span>`;
	paletteSelector.querySelector('strong').textContent=state.palette;
}
const decorateBeforeReferences=decorate;
decorate=function(){decorateBeforeReferences();decorateReferences();};

const overlayBeforeReferences=openOverlay;
openOverlay=function(kind,type='sheet') {
	overlayBeforeReferences(kind,type);
	if(kind==='effect'||kind==='palette') {
		document.querySelectorAll('#option-list .option').forEach(option=>{
			option.querySelector('.effect-thumb').outerHTML=kind==='effect'?effectThumbnail(option.dataset.name):`<span class="effect-thumb reference-palette" data-palette-id="${references.palettes.find(palette=>palette.name===option.dataset.name).id}" style="background:${paletteGradient(option.dataset.name)}"></span>`;
		});
		document.querySelector('.popover > p.small').textContent=kind==='effect'?'WLED reference colors · hover or focus to animate':'WLED palette colors · local preview';
	}
	if(kind==='info')document.querySelector('.sheet-body').insertAdjacentHTML('beforeend','<p class="sheet-note">Effect thumbnails are WLED documentation reference animations with fixed reference colors. Palette ramps use this checkout’s RGB stops; Random Cycle shows a stable sample. The scene remains a local design simulation; these are not live controller pixels.</p>');
};

// Animate only the selected effect and the hovered/focused picker option.
function previewMotion(event,animate) {
	const option=event.target.closest('#option-list .option');if(!option)return;
	if(event.relatedTarget&&option.contains(event.relatedTarget))return;
	const image=option.querySelector('img[data-animated]');if(!image)return;
	image.src=animate&&!motionPreference.matches?image.dataset.animated:image.dataset.still;
}
document.addEventListener('pointerover',event=>previewMotion(event,true));
document.addEventListener('pointerout',event=>previewMotion(event,false));
document.addEventListener('focusin',event=>previewMotion(event,true));
document.addEventListener('focusout',event=>previewMotion(event,false));
motionPreference.addEventListener('change',()=>document.querySelectorAll('img[data-animated]').forEach(image=>image.src=!motionPreference.matches&&image.dataset.previewSelected==='true'?image.dataset.animated:image.dataset.still));

// Palette changes recolor the synthetic scene, without an arbitrary hue rotation.
updateScene=function() {
	const field=document.querySelector('.scene-field');if(!field)return;
	field.style.opacity=state.on?String(.35+.35*state.bri/100):'.08';
	field.style.filter=`saturate(${1-state.white/125})`;
	const stops=paletteStops();
	document.querySelectorAll('#field stop').forEach((stop,index)=>{
		const channels=stops[Math.round(index*(stops.length-1)/3)][1];
		const rgb=state.effect==='Solid'?state.color:'rgb('+channels.join(',')+')';
		stop.setAttribute('stop-color',rgb);
		// A black palette entry emits no light; it should not paint a dark cloud.
		stop.setAttribute('stop-opacity',state.effect==='Solid'?(state.color.toLowerCase()==='#000000'?'0':'1'):(channels.some(channel=>channel>0)?'1':'0'));
	});
};
